package com.trush.game.gfx;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.graphics.Texture;
import com.badlogic.gdx.graphics.g2d.TextureRegion;
import com.badlogic.gdx.utils.Disposable;
import com.badlogic.gdx.utils.ObjectMap;

/**
 * Pixel-art sprite sheets generated by tools/gen_sprites.py. Art scale is 32 px per world unit,
 * so a region's world size is simply its pixel size / {@link #PPU}.
 */
public class Sprites implements Disposable {

    public static final float PPU = 32f;
    public static final int HERO_W = 20;
    public static final int HERO_H = 28;

    private final Texture playerTexture;
    private final Texture propsTexture;

    /** [row][col]: row 0 = front, 1 = back, 2 = roll tuck, 3 = dying (cols 0-2). Cols 0-3 walk, 4-5 idle. */
    public final TextureRegion[][] hero;
    /** Dead hero lying on his back, head to the right (28x20 px). */
    public final TextureRegion heroDead;
    private final ObjectMap<String, TextureRegion> props = new ObjectMap<>();

    public Sprites() {
        playerTexture = new Texture("assets/sprites/player.png");
        playerTexture.setFilter(Texture.TextureFilter.Nearest, Texture.TextureFilter.Nearest);
        hero = TextureRegion.split(playerTexture, HERO_W, HERO_H);
        heroDead = new TextureRegion(playerTexture, 3 * HERO_W, 3 * HERO_H + 8, 28, 20);

        propsTexture = new Texture("assets/sprites/props.png");
        propsTexture.setFilter(Texture.TextureFilter.Nearest, Texture.TextureFilter.Nearest);
        for (String line : Gdx.files.internal("assets/sprites/props.txt").readString().split("\n")) {
            String[] p = line.trim().split(" ");
            if (p.length == 5) {
                props.put(p[0], new TextureRegion(propsTexture, Integer.parseInt(p[1]), Integer.parseInt(p[2]),
                        Integer.parseInt(p[3]), Integer.parseInt(p[4])));
            }
        }
    }

    public TextureRegion prop(String name) {
        TextureRegion r = props.get(name);
        if (r == null) {
            throw new IllegalArgumentException("No prop sprite '" + name + "' in props.txt");
        }
        return r;
    }

    public static float w(TextureRegion r) {
        return r.getRegionWidth() / PPU;
    }

    public static float h(TextureRegion r) {
        return r.getRegionHeight() / PPU;
    }

    @Override
    public void dispose() {
        playerTexture.dispose();
        propsTexture.dispose();
    }
}
